update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p046","body":"تجھ کو تو گنوا دیا اب کس زخم کو ہوا دیں\nعین ممکن ہے کہ ہم اب خود کو بھی گنوا دیں\n\nدل یہ چاہتا ہے کہ ہم ایک بار کی محبت کو\nبار بار یاد کریں بار بار اسے سزا دیں\n\nاب تو یہ کیفیت سی عقل و ہوش پہ طاری ہے\nجو بھی وفا کی بات کرے اسے خوب خوب دغا دیں\n\nسوچو کہ کبھی لوٹ آئے سردی کی وہ پچھلی رت\nسوچو کہ ایسے بات کریں کہ ڈوبی کشتیاں بہا دیں\n\nہم پرانا شہر تو چھوڑ آئے پر یہ نئی بات نہ سمجھے\nکہ احمد ؔ کس کو جانے دیں اور کس کو مڑ کے صدا دیں"},{"slug":"tum-p047","body":"اک بات کا وہم سا ہے\nیہ زخم بھی مرحم سا ہے\nزندگی جس ترتیب سے ہے\nیہ کسی کا حکم سا ہے\n\nدل کی بنجر خیالی دنیا میں\nاک ہی ٹکڑا تو سَمن کا ہے\nبس شب ہی تھوڑی حُزن کی ہے\nدن تو ویسے بھی امن کا ہے\n\nخواب ہیں کہ سراب کیا معلوم\nسوچ ہے کہ کہیں فن سا ہے\nزندگی خوش باش ہے اگرچہ\nدل کا معاملہ تھوڑا اَن بَن سا ہے\n\nلکھتا ہوں اکثر زمانے کو بھی\nپر چرچا  ترے غم کا ہے\nہم  احمد ؔ سب ہی کے ہوئے\nکوئی کیوں نہ ہم کا ہے"},{"slug":"tum-p048","body":"تم مل جاتے تو کتنا اچھا ہوتا۔۔!\nاپنی داستاں بھی پھر کہانی ہوتی\nہر حادثے کا سبب مثبت لگتا\nہر گھڑی زیست جاودانی ہوتی\nتم مل جاتے تو ہم ناچیز بھی\nخوابوں کو سراب کیونکر کہتے\nآنکھوں پہ سجا کے رکھتے نہ امید\nاور فاصلوں کے عذاب کیونکر سہتے\nتم مل جاتے تو کتنا اچھا ہوتا۔۔۔!\nسلگتے ہوئے لاکھوں دلوں کو\nایک دھندلاتی ہوئی آس سیکھ جاتی\nتنہاروی کے مارے پردیسیوں کو\nگھر سی اک خانقاہ دکھ جاتی\nبارشوں سے دوستی ہوتی\nگلستاں بھی اچھے لگتے\nدل بھی تھوڑا جلتا\nلوگ بھی کچھ بھلے لگتے\nمگر تم مل جاتے تو کتنا اچھا ہوتا۔۔۔؟\nاپنی زندگی کی کہانی میں\nتب بھی بہت خم ہوتے\nغم تو آنی جانی چیز ہے\nہم مگر پھر بھی خیر ہم ہوتے"},{"slug":"tum-p049","body":"بہار چلی اب تو کئی ستمبر آئے\nتم ایسے گئے کہ پھر نہ لوٹ کر آئے\n\nہم نے چاہا بہت کہ کبھی کہیں تمہارا تزکرہ چھڑے\nکچھ تیرے مزاج کی بات ہو اور نینہ بھر آئے\n\nفرصت کہاں کہ دن بھر تجھے یاد کریں\nتو جب بھی یاد آئے شب بھر آئے\n\nہم شعر برساتے ہیں کہ تیرا ذکر امر ہو\nاور کبھی تو تیری جانب سے کوئی ابر آئے\n\nزندگی کچھ تو اچھے برے کا تسلسل رکھ\nیا ذرا دلاسہ دے کہ تھوڑا صبر آئے\n\nاتنا دلچسپ رہا اپنی تنہاروی کا سفر احمد ؔ\nجو بھی شریک سفر آئے ہمراہ جان جگر آئے"},{"slug":"tum-p050","body":"اک زمانہ تھا جب دل شاد رہا کرتا تھا\nاب وہ دور کہ نہ درد نہ شناسائی ہے\n\nمن کے ساحل پہ ہے وحشت کا صحرا\nہجر کے سویروں میں بھی گھپ تنہائی ہے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
